import { test, expect } from '@playwright/test';

test.describe('Gallery Lightbox', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('http://localhost:3000/gallery');
  });

  test('should open lightbox when clicking an image in the gallery', async ({ page }) => {
    // Get the first image in the gallery
    const firstImage = page.getByRole('img').first();

    // Click the image to open the lightbox
    await firstImage.click();

    // Verify the lightbox modal is visible
    const lightbox = page.getByRole('dialog');
    await expect(lightbox).toBeVisible();

    // Verify the image is displayed in the lightbox
    const lightboxImage = lightbox.getByRole('img');
    await expect(lightboxImage).toBeVisible();
  });

  test('should close lightbox when clicking the close button', async ({ page }) => {
    // Get and click the first image to open lightbox
    const firstImage = page.getByRole('img').first();
    await firstImage.click();

    // Verify lightbox is open
    const lightbox = page.getByRole('dialog');
    await expect(lightbox).toBeVisible();

    // Click the close button
    const closeButton = lightbox.getByRole('button', { name: /close/i });
    await closeButton.click();

    // Verify the lightbox is closed
    await expect(lightbox).not.toBeVisible();
  });

  test('should navigate between images in the lightbox using arrow buttons', async ({ page }) => {
    // Click the first image to open lightbox
    const firstImage = page.getByRole('img').first();
    await firstImage.click();

    // Verify lightbox is open
    const lightbox = page.getByRole('dialog');
    await expect(lightbox).toBeVisible();

    // Click the next button
    const nextButton = lightbox.getByRole('button', { name: /next/i });
    await nextButton.click();

    // Verify the lightbox is still visible (image changed)
    await expect(lightbox).toBeVisible();

    // Click the previous button
    const prevButton = lightbox.getByRole('button', { name: /previous/i });
    await prevButton.click();

    // Verify the lightbox is still visible
    await expect(lightbox).toBeVisible();
  });

  test('should close lightbox when pressing Escape key', async ({ page }) => {
    // Click an image to open lightbox
    const firstImage = page.getByRole('img').first();
    await firstImage.click();

    // Verify lightbox is open
    const lightbox = page.getByRole('dialog');
    await expect(lightbox).toBeVisible();

    // Press Escape key
    await page.keyboard.press('Escape');

    // Verify the lightbox is closed
    await expect(lightbox).not.toBeVisible();
  });
});
